def is_palindrome(s):
    # Skapar en variabel för att använda index
    s = list(s)

    # Om antal bokstaver är lika med antal bokstaver från början till slut
    if len(s) == len(list(reversed(s))):
        # Itererade igenom bokstaven och testar om bokstav är lika med bokstav från början
        for i in range(len(s)):
            if s[i] != s[len(s)-1-i]:
                return False
        return True

